	},
})

Translate("zhCN", "auberdine", {
	title = "奥伯丁",
	sections = {
		{
			title = "概述",
			text = [=[奥伯丁是{link:darkshore}黑海岸{/link}的港口城镇，建在面朝{link:teldrassil}泰达希尔{/link}的海岸上。它的长者{link:thundris-windweaver}桑迪斯·织风{/link}和村{link:shadow-council}议会{/link}治理着它。{link:sentinels}哨兵{/link}守卫着它，城镇中心的一口月亮井为德鲁伊和女祭司提供所需的纯净之水。{link:night-elves}暗夜精灵{/link}和{link:dwarves}矮人{/link}共用着它的旅店、{link:the-cauldron}熔炉{/link}和码头。从它的栈桥出发，一艘船驶往泰达希尔脚下的{link:rut-theran-village}鲁瑟兰村{/link}，另一艘驶往{link:menethil-harbor}米奈希尔港{/link}。如今又新开了两条航线：一条通往{link:stormwind-harbor}暴风城港口{/link}，另一条途经{link:hillsbrad-foothills}希尔斯布莱德丘陵{/link}的{link:southshore}南海镇{/link}前往米奈希尔港。城镇希望这些船能带来援助。到目前为止，它们带来的只有旅人。]=],
		},
	},
})

Translate("zhCN", "ruins-of-mathystra", {
	title = "玛塞斯特拉废墟",
	aliases = { "玛塞斯特拉" },
	sections = {
		{
			title = "概述",
			text = [=[玛塞斯特拉废墟位于{link:darkshore}黑海岸{/link}的极东北。玛塞斯特拉曾是精灵们的一座伟大堡垒，它魔法的碎片仍散落在草丛和碎石之间。如今{link:farmer-ray}雷{/link}鳞{link:naga}纳迦{/link}占据着这里，他们正在劫掠自己的祖先曾经称为家园的地方。他们的驯兽师让海中的巨兽屈从于自己的意志。最近，人们在废墟之下发现了某种更古老的东西。一个{link:elements}元素{/link}守护者曾看守着一道通往黑暗深处的阶梯，就连古树们也还不知道下面有什么。]=],
		},
	},
})

Translate("zhCN", "bashal-aran", {
	title = "巴莎兰",
	sections = {
		{
			title = "概述",
			text = [=[巴莎兰是{link:queen-azshara}艾萨拉女王{/link}为她的上层精灵建造的两座姊妹城镇之一。它的废墟位于{link:auberdine}奥伯丁{/link}以东。恶魔小鬼、劣魔和德斯里尔一伙的{link:satyrs}萨特{/link}把这里当成了巢穴，他们吸食仍附着在石头上的魔法，变得越来越强。然而在废墟西边的一座崖上有一座神龛，他们不敢靠近。一道蓝光笼罩着它。神龛中等待着{link:asterion}阿斯特利安{/link}的灵魂，他被自己的主人禁锢在那里，时间之久超过了任何在世的精灵的记忆。]=],
		},
	},
})

Translate("zhCN", "ameth-aran", {
	title = "亚米萨兰",
	sections = {
		{
			title = "概述",
			text = [=[亚米萨兰是{link:bashal-aran}巴莎兰{/link}的姊妹城镇，一座位于{link:well-of-eternity}永恒之井{/link}旁的上层精灵城镇。它毁于那场撕裂世界的战争。它的居民并没有真正死去。他们紧抓着{link:athrikus-narassin}埃瑟里克斯·纳拉辛{/link}的许诺，如今作为受诅咒、哀号的灵魂在废墟中游荡，手中仍拿着他们旧日技艺的魔法工具。石头间的两块巨大石板讲述着这座城镇和它覆灭的故事。一团古老的蓝色火焰仍在这里燃烧。它的热度足以摧毁任何其他火焰都无法触及的东西。]=],
		},
	},
})

Translate("zhCN", "tower-of-althalaxx", {
	title = "奥萨拉克斯之塔",
	sections = {
		{
			title = "概述",
			text = [=[奥萨拉克斯之塔耸立在{link:darkshore}黑海岸{/link}的东北部。它曾是{link:athrikus-narassin}埃瑟里克斯·纳拉辛{/link}的居所，这位上层精灵领主为{link:queen-azshara}艾萨拉女王{/link}统治着{link:ameth-aran}亚米萨兰{/link}和{link:bashal-aran}巴莎兰{/link}，却大部分时间远离那两座城镇，待在这里。一万年后，这座塔又有了主人。一伙自称{link:cult-of-the-dark-strand}黑暗之链教派{/link}的术士占据了它，其中最强大的人守在塔的上层。{link:auberdine}奥伯丁{/link}的一位{link:the-night-watch}守望者{/link}{link:balthule-shadowstrike}巴苏尔·影击{/link}在附近扎营。他看到塔顶闪过光芒，还听到了尖叫声。]=],
		},
	},
})

Translate("zhCN", "grove-of-the-ancients", {
	title = "古树之林",
	sections = {
		{
			title = "概述",
			text = [=[古树之林位于{link:darkshore}黑海岸{/link}南部，受群山庇护。这里居住着古树，它们是森林的伟大灵魂，自最古老的岁月起便与{link:night-elves}暗夜精灵{/link}并肩而立。知识古树奥努收集着这片土地上每一个威胁的消息，{link:auberdine}奥伯丁{/link}的德鲁伊们听从他的警告。站在他身旁的是战争古树{link:arbal}阿尔巴尔{/link}。这片{link:moonglade}林地{/link}和所有古树一样富有耐心，但它并非无所作为。对抗{link:naga}纳迦{/link}和{link:twilight-s-hammer}暮光之锤{/link}的斗争正在这里悄然谋划。]=],
		},
	},
})

Translate("zhCN", "twilight-vale", {
	title = "暮光谷",
	sections = {
		{
			title = "概述",
			text = [=[暮光谷是{link:darkshore}黑海岸{/link}南部森林的名称，从{link:ameth-aran}亚米萨兰{/link}的废墟一直延伸到{link:ashenvale}灰谷{/link}的边境。它的道路连接着{link:auberdine}奥伯丁{/link}与{link:maestra-s-post}迈斯特拉岗哨{/link}和{link:astranaar}阿斯特兰纳{/link}，信使们在这些路上行走时冒着生命危险。{link:blackwood-furbolgs}黑木熊怪{/link}伏击旅人，月夜猎豹在林间潜行，森林里患病的熊会攻击任何靠近的人。{link:grove-of-the-ancients}古树之林{/link}、{link:the-master-s-glaive}主宰之剑{/link}和{link:explorers-league}探险者协会{/link}的挖掘场都位于这座{link:stranglethorn-vale}山谷{/link}中。在这里旅行的人都不敢离开大路。]=],
		},
	},
})

Translate("zhCN", "mist-s-edge", {
	title = "薄雾海",
	sections = {
		{
			title = "概述",
			text = [=[薄雾海是沿着{link:darkshore}黑海岸{/link}延伸的一片长长的灰色水域，{link:cliffspring-river}壁泉河{/link}在这里注入大海。它的海滩上散落着巨大海洋生物的尸体和船只的残骸。其中两艘船，银色破晓号和薄雾面纱号，沉在{link:auberdine}奥伯丁{/link}以北的海底，它们在进港时被{link:murlocs}鱼人{/link}击沉。螃蟹在每一片沙滩上横行。灰雾鱼人沿着海岸搭起他们的棚屋，他们的首领既猎杀渔夫，也猎杀{link:sentinels}哨兵{/link}。]=],
		},
	},
})

Translate("zhCN", "cliffspring-river", {
	title = "壁泉河",
	sections = {
		{
			title = "概述",
			text = [=[壁泉河从东部群山流下，在{link:auberdine}奥伯丁{/link}以北汇入大海。一座桥横跨在它的第一道瀑布之上。它的河水曾经清澈。如今正变得污浊，奥伯丁的长者担心污染会蔓延到城镇本身。{link:blackwood-furbolgs}黑木熊怪{/link}的北方营地沿着河岸分布，他们的篝火在水边燃烧。{link:thundris-windweaver}桑迪斯·织风{/link}相信是{link:furbolgs}熊怪{/link}污染了河水，但毒害的真正根源在更远的东方，在{link:felwood}费伍德森林{/link}。]=],
		},
	},
})

Translate("zhCN", "cliffspring-falls", {
	title = "峭壁之泉",
	sections = {
		{
			title = "概述",
			text = [=[峭壁之泉从{link:auberdine}奥伯丁{/link}以东的群山上倾泻而下。这一带大部分地方都饮用它的水，如今一种毒素在水中流淌，让{link:darkshore}黑海岸{/link}的鹿群染上疾病。瀑布后面有一个洞穴，里面生长着稀有的蘑菇。古树们警告奥伯丁的居民远离那里，因为他们察觉到一种新的邪恶在那里安了家。他们是对的。{link:naga}纳迦{/link}占据了这个洞穴，率领他们的是一位名叫{link:lord-sinslayer}屠罪者{/link}的纳迦领主。]=],
		},
	},
})

Translate("zhCN", "blackwood-den", {
	title = "黑木洞穴",
	sections = {
		{
			title = "概述",
			text = [=[黑木洞穴位于{link:darkshore}黑海岸{/link}的最南端，靠近{link:ashenvale}灰谷{/link}边境。它是围绕着一个小洞穴的一群{link:furbolgs}熊怪{/link}营地，属于{link:blackwood-furbolgs}黑木部族{/link}。一位名叫{link:volcor}沃科尔{/link}的{link:night-elves}暗夜精灵{/link}在这里被熊怪打伤，躲进了洞穴深处。他忠实的伙伴恐爪独自北上寻求帮助。这个洞穴是熊怪堕落之深的严峻标志。他们曾与精灵和平共处。如今他们攻击任何靠近他们篝火的精灵。]=],
		},
	},
})

Translate("zhCN", "remtravel-s-excavation", {
	title = "雷姆塔维尔挖掘场",
	aliases = { "雷姆塔维尔的挖掘场" },
	sections = {
		{
			title = "概述",
			text = [=[雷姆塔维尔挖掘场是{link:explorers-league}探险者协会{/link}在{link:darkshore}黑海岸{/link}西南部的挖掘场。{link:prospector-remtravel}勘察员雷塔维{/link}和他的队员在这里发现了一个伟大古老社会的迹象。随后大地本身转而与他们为敌。石头魔像从地下升起，占领了挖掘场，砾燧{link:troggs}石腭怪{/link}也随之而来。队员们逃回了{link:auberdine}奥伯丁{/link}。勘察员没有走。他仍在挖掘场的某处，寻找一块他已经弄丢过一次的神秘化石。至于探险者协会会如何看待这块化石，奥伯丁没有人说得清。]=],
		},
	},
})

Translate("zhCN", "the-master-s-glaive", {
	title = "主宰之剑",
	sections = {
		{
			title = "概述",
			text = [=[主宰之剑矗立在{link:darkshore}黑海岸{/link}南部：一把插进一具倒下巨人头骨中的巨刃。奥努教导说，一位古老的大地领主在远古时代死在这里，被这把剑刃刺穿。这位领主早已死去，但他力量的碎屑或许仍留在他的骨头里。{link:twilight-s-hammer}暮光之锤{/link}前来寻找它们。他们的邪教徒在剑刃下扎营，他们的书中有一些古老精灵魔法的书页，被扭曲用来把他们古老的主人召回这个世界。]=],
		},
	},
})

Translate("zhCN", "thundris-windweaver", {
