			text = [=[{link:auberdine}奥伯丁{/link}以南的营地比特伦希斯担心的还要糟糕。{link:blackwood-furbolgs}黑木熊怪{/link}已被腐化，而且近在咫尺。他告诉奥伯丁为必将到来的一切做好准备。他也告诉在那里战斗过的人不必悲伤。他们削弱了威胁，即使邪能苔藓仍在毒害这片土地。]=],
		},
		{
			title = "失踪的主人",
			hint = "回应那头独自来到奥伯丁的野兽的呼唤。",
			text = [=[恐爪在没有主人陪伴的情况下来到了{link:auberdine}奥伯丁{/link}。特伦希斯立刻明白了。{link:volcor}沃科尔{/link}受了伤，就在南方{link:furbolgs}熊怪{/link}之间的某个地方。他缝制了一件能让穿戴者在野兽面前隐藏行迹的斗篷，并警告说，如果穿戴者除了说话之外还做了别的事，斗篷的魔法就会失效。]=],
		},
	},
	mentions = {
		{ text = "失踪的主人" },
