	},
	bonds = {
		{ id = "volcor", name = "沃科尔", note = "他的朋友" },
		{ id = "grimclaw", name = "锐爪", note = "沃科尔的伙伴" },
		{ id = "thundris-windweaver", name = "桑迪斯·织风", note = "他所汇报的长者" },
