	sections = {
		{
			title = "概述",
			text = [=[安努是一棵知识古树，森林的伟大灵魂之一，他守护着{link:darkshore}黑海岸{/link}南部的{link:grove-of-the-ancients}古树之林{/link}。他说话缓慢，停顿很长，从不着急。他知道万物都会在注定的时刻到来。]=],
		},
		{
			title = "意义",
			text = [=[安努是{link:darkshore}黑海岸{/link}的记忆。他知道{link:twilight-s-hammer}暮光之锤{/link}的邪教徒崇拜什么，也知道他们的一位古老领主倒在了哪里。{link:auberdine}奥伯丁{/link}的德鲁伊和学者把他们最重大的问题送到他这里，大德鲁伊{link:fandral-staghelm}范达尔·鹿盔{/link}也从{link:darnassus}达纳苏斯{/link}给他送来消息。]=],
		},
		{
			title = "事迹",
			text = [=[• 他派{link:the-night-watch}守望者{/link}前往{link:the-master-s-glaive}主宰之剑{/link}，得知{link:twilight-s-hammer}暮光之锤{/link}就在那里。
• 他研究了从教派典籍上撕下的一页，从中察觉到了古老者的魔法。
• 他从{link:ruins-of-mathystra}玛塞斯特拉{/link}收集遗物，以了解该教派如何利用精灵的魔法。
• 他谈到{link:malfurion-stormrage}怒风导师{/link}，说他理解森林的耐心。]=],
		},
	},
	chapters = {
		{
			title = "主宰之剑",
			hint = "应古树的请求前往主宰之剑。",
			text = [=[安努觉得{link:naga}纳迦{/link}来到{link:darkshore}黑海岸{/link}很奇怪。{link:twilight-s-hammer}暮光之锤{/link}的到来则更加奇怪。当他的担忧得到证实时，他讲述了那位被刺穿在{link:the-master-s-glaive}主宰之剑{/link}上的古老领主。那位领主已经死了。他的力量，或许还没有。]=],
		},
		{
			title = "古老者的书页",
			hint = "把从教派营地夺来的东西带给古树。",
			text = [=[从暮光典籍上撕下的潦草字迹中蕴含着一种混乱的魔法，而在它下面是精灵的文字。该教派正在利用古老的精灵巫术，把它古老的主人们带回这个世界。安努着手研究其方法，要赶在敌人完成他们已经开始的事情之前。]=],
		},
		{
			title = "玛塞斯特拉之下的阶梯",
			hint = "把玛塞斯特拉守护者的遗留之物带给古树。",
			text = [=[当那颗浑浊的水球被放在他面前时，安努露出了近乎惊讶的神情。{link:ruins-of-mathystra}玛塞斯特拉{/link}之下有一道阶梯，曾有一个守护者看守着它。他只说他必须与其他古树商议，并说幸好在{link:naga}纳迦{/link}或教派找到这道阶梯之前，它就已经被发现了。]=],
		},
	},
	mentions = {
		{ text = "安努，由{link:barithras-moonshade}巴瑞萨斯·月影{/link}召唤" },
		{ text = "{link:twilight-base-camp}暮光营地{/link}" },
		{
			text = [=[{link:grove-of-the-ancients}古树之林{/link}，来自{link:fandral-staghelm}范达尔·鹿盔{/link}的消息]=],
		},
	},
	bonds = {
		{ id = "arbal", name = "阿尔巴尔", note = "与他一同守在林地中" },
		{ id = "barithras-moonshade", name = "巴瑞萨斯·月影", note = "听从他的警告" },
		{ id = "fandral-staghelm", name = "范达尔·鹿盔", note = "给他送来消息" },
		{ id = "baron-marinous", name = "玛里诺斯男爵", note = "玛塞斯特拉的守护者" },
	},
})

